// Formats an amount in integer cents as a sign, whole currency units and exactly
// two fraction digits, with no currency symbol: 123 -> "1.23", -5 -> "-0.05", 0 -> "0.00".
export function formatAmount(cents: number): string {
  const sign = cents < 0 ? '-' : '';
  const absolute = Math.abs(cents);
  return sign + Math.floor(absolute / 100) + '.' + String(absolute % 100).padStart(2, '0');
}

